  styleUrls: ['./multi-tree-list.component.css']
})
export class MultiTreeListComponent {
  // Example data
  data = [
    { id: 0, name: 'Root', children: [{ id: 1, name: 'Child 1' }, { id: 2, name: 'Child 2' }] },
    { id: 3, name: 'Parent', children: [{ id: 4, name: 'Grandchild 1' }] }
  ];

  constructor() {}

  expandNode(id: number): void {
    this.data.forEach(node => {
      if (node.id === id) {
        node.expanded = true;
        this.expandChildren(node);
      }
