  }

  collapseNode(id: number): void {
    this.data.forEach(node => {
      if (node.id === id) {
        node.expanded = false;
      }
    });
  }

  private expandChildren(parent: TreeNode | TreeItem): void {
    const children = parent.children || [];
    children.forEach(child => {
      child.expanded = true;
      this.expandChildren(child);
    });
  }
}
```

